// Support local likes/dislikes since the real backend doesn't save them
const [localLikes, setLocalLikes] = useState((hash % 12) + 1);
const [dislikes, setDislikes] = useState(hash % 3);
const [localLiked, setLocalLiked] = useState(false);
const [disliked, setDisliked] = useState(false);

const hasLikeApi = onToggleLike !== undefined;
const likes = hasLikeApi ? (likeCount ?? 0) : localLikes;
const liked = hasLikeApi ? !!isLikedByCurrentUser : localLiked;

const handleLike = () => {
  if (hasLikeApi) {
    onToggleLike?.();
  } else {
    if (localLiked) {
      setLocalLikes(l => l - 1);
      setLocalLiked(false);
    } else {
      setLocalLikes(l => l + 1);
      setLocalLiked(true);
      if (disliked) {
        setDislikes(d => d - 1);
        setDisliked(false);
      }
    }
  }
};

const handleDislike = () => {
  // 踩功能仅支持本地模式（无对应后端 API）
  if (disliked) {
    setDislikes(d => d - 1);
    setDisliked(false);
  } else {
    setDislikes(d => d + 1);
    setDisliked(true);
    if (liked && !hasLikeApi) {
      setLocalLikes(l => l - 1);
      setLocalLiked(false);
    }
  }
};

