1	package com.cc91.forumservice.controller;
2	
3	import com.cc91.forumservice.client.CreateNotificationRequest;
4	import com.cc91.forumservice.client.NotificationServiceClient;
5	import com.cc91.forumservice.client.UserInfoDTO;
6	import com.cc91.forumservice.client.UserServiceClient;
7	import com.cc91.forumservice.dto.ApiResponse;
8	import com.cc91.forumservice.dto.PostResponse;
9	import com.cc91.forumservice.dto.UpdatePostStatusRequest;
10	import com.cc91.forumservice.entity.Comment;
11	import com.cc91.forumservice.entity.Post;
12	import com.cc91.forumservice.exception.ResourceNotFoundException;
13	import com.cc91.forumservice.repository.CommentRepository;
14	import com.cc91.forumservice.repository.PostRepository;
15	import com.cc91.forumservice.service.PostService;
16	import org.slf4j.Logger;
17	import org.slf4j.LoggerFactory;
18	import org.springframework.http.ResponseEntity;
19	import org.springframework.security.access.prepost.PreAuthorize;
20	import org.springframework.transaction.annotation.Transactional;
21	import org.springframework.web.bind.annotation.*;
22	
23	import java.util.List;
24	import java.util.Map;
25	import java.util.Set;
26	import java.util.stream.Collectors;
27	
28	@RestController
29	@RequestMapping("/api/admin")
30	@PreAuthorize("hasRole('ADMIN')")
31	public class AdminContentController {
32	
33	    private static final Logger logger = LoggerFactory.getLogger(AdminContentController.class);
34	
35	    private final PostRepository postRepository;
36	    private final CommentRepository commentRepository;
37	    private final PostService postService;
38	    private final NotificationServiceClient notificationServiceClient;
39	    private final UserServiceClient userServiceClient;
40	
41	    public AdminContentController(PostRepository postRepository,
42	                                  CommentRepository commentRepository,
43	                                  PostService postService,
44	                                  NotificationServiceClient notificationServiceClient,
45	                                  UserServiceClient userServiceClient) {
46	        this.postRepository = postRepository;
47	        this.commentRepository = commentRepository;
48	        this.postService = postService;
49	        this.notificationServiceClient = notificationServiceClient;
50	        this.userServiceClient = userServiceClient;
51	    }
52	
53	    @GetMapping("/posts")
54	    public ResponseEntity<List<PostResponse>> getPostsByStatus(
55	            @RequestParam(required = false) String status
56	    ) {
57	        List<PostResponse> response = postService.getPostList(0, 1000, status).getContent();
58	        return ResponseEntity.ok(response);
59	    }
60	
61	    @GetMapping("/comments")
62	    public ResponseEntity<List<Map<String, Object>>> getComments() {
63	        List<Comment> comments = commentRepository.findAllWithPostByOrderByCreatedAtDesc();
64	
65	        Set<Long> authorIds = comments.stream()
66	                .map(Comment::getAuthorId)
67	                .collect(Collectors.toSet());
68	
69	        Map<Long, UserInfoDTO> userMap;
70	        try {
71	            List<UserInfoDTO> users = userServiceClient.getUsersByIds(List.copyOf(authorIds));
72	            userMap = users.stream().collect(Collectors.toMap(UserInfoDTO::getId, u -> u));
73	        } catch (Exception e) {
74	            logger.warn("批量查询用户信息失败: {}", e.getMessage());
75	            userMap = Map.of();
76	        }
77	        final Map<Long, UserInfoDTO> finalUserMap = userMap;
78	
79	        List<Map<String, Object>> result = comments.stream().map(c -> {
80	            UserInfoDTO author = finalUserMap.get(c.getAuthorId());
81	            String postTitle = c.getPost() != null ? c.getPost().getTitle() : "未知帖子";
82	            return Map.<String, Object>of(
83	                    "id", c.getId(),
84	                    "postId", c.getPostId(),
85	                    "postTitle", postTitle,
86	                    "authorId", c.getAuthorId(),
87	                    "authorUsername", author != null ? author.getUsername() : "未知用户",
88	                    "content", c.getContent(),
89	                    "parentId", c.getParentId() != null ? c.getParentId() : 0L,
90	                    "status", c.getStatus(),
91	                    "createdAt", c.getCreatedAt().toString()
92	            );
93	        }).collect(Collectors.toList());
94	
95	        return ResponseEntity.ok(result);
96	    }
97	
98	    @PutMapping("/posts/{id}/status")
99	    @Transactional
100	    public ResponseEntity<ApiResponse<Void>> updatePostStatus(
101	            @PathVariable Long id,
102	            @RequestBody UpdatePostStatusRequest request
103	    ) {
104	        Post post = postRepository.findById(id)
105	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
106	
107	        post.setStatus(request.getStatus());
108	        postRepository.save(post);
109	
110	        try {
111	            notificationServiceClient.createNotification(new CreateNotificationRequest(
112	                    post.getAuthorId(), "POST_STATUS", "帖子状态变更",
113	                    "您的帖子「" + post.getTitle() + "」状态已变更为：" + request.getStatus(),
114	                    post.getId()
115	            ));
116	        } catch (Exception e) {
117	            logger.warn("通知发送失败: postId={}", id, e);
118	        }
119	
120	        logger.info("管理员修改帖子状态: id={}, status={}", id, request.getStatus());
121	        return ResponseEntity.ok(ApiResponse.success("帖子状态已更新"));
122	    }
123	
124	    @DeleteMapping("/posts/{id}")
125	    public ResponseEntity<ApiResponse<Void>> forceDeletePost(@PathVariable Long id) {
126	        Post post = postRepository.findById(id)
127	                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));
128	        postRepository.delete(post);
129	        logger.info("管理员强制删除帖子: id={}", id);
130	        return ResponseEntity.ok(ApiResponse.success("帖子已删除"));
131	    }
132	
133	    @DeleteMapping("/comments/{id}")
134	    public ResponseEntity<ApiResponse<Void>> forceDeleteComment(@PathVariable Long id) {
